import { createServer } from 'dhcp';

const server = createServer({
    range: ['192.168.1.10', '192.168.1.99'],
    server: '192.168.1.1',
    optionDefinitions: {
        252: {
            name: 'WPAD URL',
            type: 'ASCII',
        },
    },
    ackOptions: {
        252: 'http://wpad.example/wpad.dat',
    },
});

server.listen();
